// Normalize Firecrawl /v1/scrape response into ScrapedItem shape
const webhookData = $('Webhook').item.json.body;
const fc = $input.first().json;

const extracted = fc?.data?.json ?? {};
const markdown = fc?.data?.markdown ?? '';
const metadata = fc?.data?.metadata ?? {};

const item = {
  source_run_id: fc?.data?.metadata?.sourceURL || webhookData.source.url,
  source_url: webhookData.source.url,
  scraped_at: new Date().toISOString(),
  payload: {
    kind: 'product_page',
    brand: metadata.ogSiteName || metadata.siteName,
    title: extracted.title || metadata.title || '',
    description_md: markdown.slice(0, 8000),
    price: extracted.price,
    image_urls: extracted.image_urls || [],
    claims: extracted.claims || [],
  },
  destination: webhookData.destination,
  job_id: webhookData.job_id,
  callback_url: webhookData.callback_url,
  raw: fc?.data ?? {},
};

return [{ json: item }];
